arguments.content:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# the header line and the other room's booking stay as they were
want=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')
[ "$(cat "$t")" = "$want" ] || { echo "file after cancel: $(cat "$t")"; fail=1; }
# not found: exit 1, nothing on stdout, message on stderr
nf_out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); nf_rc=$?
[ $nf_rc = 1 ] || { echo "not found should exit 1, got $nf_rc"; fail=1; }
[ -z "$nf_out" ] || { echo "not found should print nothing to stdout: $nf_out"; fail=1; }
nf_err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$nf_err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $nf_err"; fail=1; }
# usage: exit 2, nothing on stdout, usage on stderr
u_out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); u_rc=$?
[ $u_rc = 2 ] || { echo "usage should exit 2, got $u_rc"; fail=1; }
[ -z "$u_out" ] || { echo "usage should print nothing to stdout: $u_out"; fail=1; }
u_err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$u_err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage on stderr: $u_err"; fail=1; }
rm -f "$t"
# same date and start in another room: only the named room's booking goes
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
out2=$(BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel (other room) failed"; fail=1; }
[ "$out2" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel (other room) output: $out2"; fail=1; }
want2=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty')
[ "$(cat "$t2")" = "$want2" ] || { echo "other room's booking removed: $(cat "$t2")"; fail=1; }
rm -f "$t2"; exit $fail

